  'That time is at another clinic. Book it as a new visit instead.': 'এই সময়টা অন্য ক্লিনিকের। নতুন ভিজিট হিসেবে বুক করুন।',
  'That time was just taken. Choose another.': 'ওই সময়টা এইমাত্র বুক হয়ে গেছে। অন্য সময় বেছে নিন।',
  'The AI assistant only uses this entry once a doctor approves it.': 'ডাক্তার অনুমোদন দিলে তবেই AI সহকারী এই এন্ট্রি ব্যবহার করে।',
  'The AI assistant uses this entry in its answers.': 'AI সহকারী উত্তরে এই এন্ট্রি ব্যবহার করে।',
  'The app logs me out every few days and I have to enter the OTP again. Very tiring.': 'অ্যাপ কয়েক দিন পরপর আমাকে লগ আউট করে দেয় আর আবার OTP দিতে হয়। খুব ক্লান্তিকর।',
  'The bank and branch fill in from the IFSC (on your cheque book or bank app)': 'ব্যাংক ও শাখা IFSC থেকে ভরে যায় (চেক বই বা ব্যাংকের অ্যাপে আছে)',
  'The clinic confirms the time. You can chat with the doctor once the visit is booked.': 'ক্লিনিক সময় নিশ্চিত করবে। ভিজিট বুক হলে ডাক্তারের সঙ্গে চ্যাট করতে পারবেন।',
  'The clinic has been told. Someone will reply here.': 'ক্লিনিককে জানানো হয়েছে। কেউ এখানে উত্তর দেবেন।',
  'The clinic is closed for every doctor': 'ক্লিনিক সব ডাক্তারের জন্য বন্ধ',
