  'Watches and rings send their readings to MedPin through Health Connect — get it, then come back and tap Connect.': 'ঘড়ি আর রিং Health Connect দিয়ে MedPin-এ মান পাঠায় — সেটা নিয়ে ফিরে এসে Connect চাপুন।',
  'We couldn\'t check it automatically — your doctor will look at it.': 'আমরা নিজে থেকে যাচাই করতে পারিনি — ডাক্তার দেখে নেবেন।',
  'We couldn\'t find the tests in this file.': 'এই ফাইলে টেস্ট খুঁজে পাওয়া যায়নি।',
  'We couldn\'t read the report you uploaded on #1. Try a clearer photo or the lab\'s PDF.': '#1 তারিখে আপলোড করা রিপোর্টটি পড়া যায়নি। আরও পরিষ্কার ছবি বা ল্যাবের PDF দিন।',
  'We couldn\'t read this report': 'আমরা এই রিপোর্টটি পড়তে পারিনি',
  'We don\'t have your clinic\'s number. In an emergency, call #1.': 'আপনার ক্লিনিকের নম্বর আমাদের কাছে নেই। জরুরি অবস্থায় #1-এ কল করুন।',
  'We flag anything out of range and explain it simply.': 'সীমার বাইরে কিছু থাকলে আমরা জানাই আর সহজ করে বুঝিয়ে দিই।',
  'We found #1 in it.': 'এতে #1 পাওয়া গেছে।',
  'We found #1 test in this file.': 'এই ফাইলে #1টি টেস্ট পাওয়া গেছে।',
  'We found #1 tests in this file.': 'এই ফাইলে #1টি টেস্ট পাওয়া গেছে।',
  'We found your location but not the address. Type your address below — distances will still be right.': 'লোকেশন পাওয়া গেছে কিন্তু ঠিকানা নয়। নিচে ঠিকানা লিখুন — দূরত্ব ঠিকই থাকবে।',
  'We read it for you, summarise it in simple words and flag anything out of range.': 'আমরা পড়ে সহজ কথায় সারাংশ দিই আর সীমার বাইরে কিছু থাকলে জানাই।',
  'We read medicines in it, not test results. Save it as a prescription?': 'এতে ওষুধ পাওয়া গেছে, পরীক্ষার ফল নয়। প্রেসক্রিপশন হিসেবে রাখবেন?',
  'We read test results in it, not a prescription. Save it as a test report so its values are tracked?': 'এতে পরীক্ষার ফল পাওয়া গেছে, প্রেসক্রিপশন নয়। পরীক্ষার রিপোর্ট হিসেবে রাখবেন, যাতে মানগুলো দেখা যায়?',
  'We read the report to check it’s this test — the file name doesn’t matter.': 'এটা সেই পরীক্ষারই রিপোর্ট কিনা আমরা পড়ে দেখি — ফাইলের নাম গুরুত্বপূর্ণ নয়।',
  'We read these from the document. Change anything that isn’t right.': 'এগুলো কাগজ থেকে পড়া হয়েছে। ভুল থাকলে বদলে দিন।',
  'We remind you to take your medicines at these times.': 'এই সময়ে আমরা আপনাকে ওষুধ খাওয়ার কথা মনে করিয়ে দেব।',
  'We reply by email or phone, usually within a working day.': 'আমরা ইমেল বা ফোনে উত্তর দিই, সাধারণত এক কাজের দিনের মধ্যে।',
  'We tailor your profile to it. A psychologist sets session length and therapy approaches; ': 'আপনার প্রোফাইল সেই অনুযায়ী সাজানো হয়। মনোবিদ সেশনের দৈর্ঘ্য ও থেরাপির ধরন ঠিক করেন; ',
  'We tailor your profile to it. A psychologist sets session length and therapy approaches; a physiotherapist can offer home visits.': 'আপনার প্রোফাইল সেই অনুযায়ী সাজানো হয়। মনোবিদ সেশনের দৈর্ঘ্য ও থেরাপির ধরন ঠিক করেন; ফিজিওথেরাপিস্ট বাড়িতে গিয়ে দেখতে পারেন।',
  'We will check with your clinics, then delete your account and tell you by SMS.': 'আমরা আপনার ক্লিনিকের সঙ্গে কথা বলে অ্যাকাউন্ট মুছে দেব এবং SMS-এ জানাব।',
  'We won\'t create a duplicate. Ask the patient for the consent code shown in their MedPin app to link their record to your practice.': 'আমরা দ্বিতীয় রেকর্ড বানাব না। রেকর্ড আপনার প্র্যাকটিসে যুক্ত করতে রোগীর MedPin অ্যাপে দেখানো সম্মতি কোড চান।',
  'We\'ll remind you at #1:#2 AM if nothing is logged': 'কিছু লেখা না থাকলে #1:#2 AM-এ মনে করিয়ে দেব',
  'We\'ll remind you at #1:#2 PM if nothing is logged': 'কিছু লেখা না থাকলে #1:#2 PM-এ মনে করিয়ে দেব',
  'We\'ll send a code to this number to confirm it': 'নিশ্চিত করতে এই নম্বরে একটি কোড পাঠানো হবে',
  'We\'ll text a #1-digit code to check it\'s your number. MedPin fills it in for you.': 'নম্বরটি আপনার কিনা দেখতে আমরা #1-অঙ্কের কোড পাঠাব। MedPin নিজেই সেটা বসিয়ে দেবে।',
  'We\'re checking your payment with the bank. It will show as paid in a few minutes — no need to pay again.': 'আপনার পেমেন্ট ব্যাংকের সঙ্গে মিলিয়ে দেখা হচ্ছে। কয়েক মিনিটে পেমেন্ট হয়ে গেছে দেখাবে — আবার পেমেন্ট করবেন না।',
