  'Welcome to MedPin': 'MedPin-এ স্বাগতম',
  'We’ll contact you to confirm. Patient records your practice keeps by law are not deleted; your sign-in and profile are.': 'নিশ্চিত করতে আমরা যোগাযোগ করব। আইন অনুযায়ী আপনার প্র্যাকটিস যে রোগীর রেকর্ড রাখে তা মোছা হয় না; আপনার সাইন ইন ও প্রোফাইল মোছা হয়।',
