  'Your steps come from your phone. Watches and rings send their readings to MedPin through Health Connect — get it, then come back and tap Connect.': 'আপনার স্টেপ ফোন থেকে আসে। ঘড়ি আর রিং Health Connect দিয়ে MedPin-এ মান পাঠায় — সেটা নিয়ে ফিরে এসে Connect চাপুন।',
  'Your sugar has crept up a little since July (HbA#1c #2%) and bad cholesterol (LDL) is still high. ': 'জুলাই থেকে আপনার সুগার একটু বেড়েছে (HbA#1c #2%) আর খারাপ কোলেস্টেরল (LDL) এখনও বেশি। ',
